(function(root){'use strict';function state(s){if(!s||typeof s.session!=='string'||!s.session||s.session.length>128)return null;return{session:s.session,enabled:s.enabled===true,fullscreen:s.fullscreen===true,display:s.display===true,source:s.source==='pq-bt2020'?'pq-bt2020':'other',output:s.output==='pq-confirmed'?'pq-confirmed':'sdr',toneModes:Array.isArray(s.toneModes)?s.toneModes.filter(x=>['auto','detail','brightness'].includes(x)):[]}}function eligible(s){return !!(s&&s.enabled&&s.fullscreen&&s.display&&s.source==='pq-bt2020')}function badge(s){return s?.output==='pq-confirmed'?'HDR output confirmed':'SDR output'}function request(s,mode,tone){if(!s||!['auto','sdr'].includes(mode))throw Error('STATE');if(mode==='auto'&&!eligible(s))throw Error('UNAVAILABLE');if(!s.toneModes.includes(tone))throw Error('TONE_UNAVAILABLE');return{session:s.session,mode,tone}}const api={state,eligible,badge,request};if(typeof module==='object')module.exports=api;else root.HDR=api})(globalThis);
